provider "aws" {
  region = "us-east-1"
}

resource "aws_db_option_group" "example" {
  name                     = "option-group-pike"
  option_group_description = "Terraform Option Group"
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  option {
    db_security_group_memberships  = []
    option_name                    = "SQLSERVER_AUDIT"
    port                           = 0
    vpc_security_group_memberships = []

    option_settings {
      name  = "IAM_ROLE_ARN"
      value = "arn:aws:iam::680235478471:role/aws-service-role/rds.amazonaws.com/AWSServiceRoleForRDS"
    }
    option_settings {
      name  = "S3_BUCKET_ARN"
      value = "arn:aws:s3:::testbucketineu-west2/rds"
    }
  }

  option {
    option_name = "TDE"
    port        = 0
  }

  tags = {
    pike = "permissions"
  }
}

responsePreview:
This Terraform configuration defines an AWS RDS option group named `option-group-pike` for the `sqlserver-ee` engine using SQL Server major engine version `11.00`. It enables both required options: `SQLSERVER_AUDIT` and `TDE`. Because SQL Server Audit requires an S3 destination and IAM permissions, the configuration also creates an S3 bucket, IAM role, and IAM policy for RDS to write audit logs.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "sqlserver_audit" {
  bucket = "option-group-pike-sqlserver-audit-${random_id.suffix.hex}"

  tags = {
    Name = "option-group-pike-sqlserver-audit"
  }
}

